<?php if(!function_exists('identity_change')){http_response_code(404);exit;}
function identity_system_options(string $selected):void{foreach(['user'=>'Utilisateur','admin'=>'Administrateur logiciel','ossi'=>'OSSI'] as $value=>$label)echo '<option value="'.$value.'" '.($value===$selected?'selected':'').'>'.$label.'</option>';}
?>
<section class="panel"><div class="section-heading"><div><h2>Utilisateurs et rôles</h2><p>Comptes Windows/AD et comptes internes Ogipen dans une même liste. Le rôle technique et les droits du projet sont indépendants.</p></div><span class="license-badge"><?=h($identityUsed)?> actifs · quotas par entreprise</span></div>
<p>Attribuez ici le rôle <strong>Utilisateur</strong>, <strong>Administrateur logiciel</strong> ou <strong>OSSI</strong> au compte déclaré. Le changement ferme ses sessions : il prendra effet à la prochaine connexion.</p>
<?php if(!$identityRows):?><div class="empty-state"><h3>Aucun utilisateur enregistré</h3><p>Ajoutez une identité Windows/AD ci-dessous, ou créez un <a href="<?=h(url('/?page=accounts'))?>">compte interne Ogipen</a>.</p></div><?php else:?>
<table class="identity-roles"><thead><tr><th>Utilisateur</th><th>Connexion</th><th>Rôle technique</th><th>Droits du projet</th><th>État</th><th>Actions</th></tr></thead><tbody>
<?php foreach($identityRows as $i):?><tr><td><strong><?=h($i['display_name'])?></strong><br><code><?=h($i['id'])?></code></td><td><?=h($i['login_name']!==null?'Ogipen : '.$i['login_name']:'Windows / AD')?></td>
<td><form method="post" action="<?=h(url('/?page=identities'))?>"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="identity_system_role"><input type="hidden" name="identity_id" value="<?=h($i['id'])?>"><input type="hidden" name="revision" value="<?=h($i['auth_version'])?>"><select name="system_role" aria-label="Rôle technique de <?=h($i['display_name'])?>"><?php identity_system_options($i['system_role']);?></select><button>Appliquer</button></form></td>
<td><?=h($i['can_edit']?'Lecture et édition':($i['can_read']?'Lecture seule':'Aucun accès'))?></td><td><?=$i['enabled']?'Actif':'Inactif'?></td><td><a class="button-link" href="<?=h(url('/?page=identities&edit='.rawurlencode($i['id'])))?>">Modifier</a><form class="inline-action" method="post" action="<?=h(url('/?page=identities'))?>"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="identity_toggle"><input type="hidden" name="identity_id" value="<?=h($i['id'])?>"><input type="hidden" name="revision" value="<?=h($i['auth_version'])?>"><input type="hidden" name="enabled" value="<?=$i['enabled']?'0':'1'?>"><button class="<?=$i['enabled']?'danger':''?>"><?=$i['enabled']?'Désactiver':'Activer'?></button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section>
<section class="panel"><h2><?=$identityEdit?'Modifier l’utilisateur':'Ajouter une identité Windows / AD'?></h2>
<?php $internal=$identityEdit && $identityEdit['login_name']!==null;?>
<?php if(!$identityEdit):?><p>Pour un compte interne avec mot de passe Ogipen, utilisez <a href="<?=h(url('/?page=accounts'))?>">Comptes Ogipen</a>. Il apparaîtra ensuite dans cette liste.</p><?php endif;?>
<form class="identity-form" method="post" action="<?=h(url('/?page=identities'))?>"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="<?=$identityEdit?'identity_save':'identity_create'?>"><input type="hidden" name="revision" value="<?=h($identityEdit['auth_version']??'')?>">
<div class="form-grid"><label>Identifiant<input name="identity_id" maxlength="80" required value="<?=h($identityEdit['id']??'')?>" <?=$identityEdit?'readonly':''?> autocomplete="off"></label><label>Nom affiché<input name="display_name" maxlength="180" required value="<?=h($identityEdit['display_name']??'')?>" autocomplete="off"></label><label>Rôle technique<select name="system_role"><?php identity_system_options($identityEdit['system_role']??'user');?></select></label><label>Droits du projet<select name="role"><?php $role=$identityEdit?($identityEdit['can_edit']?'editor':($identityEdit['can_read']?'reader':'none')):'reader';foreach(['reader'=>'Lecture seule','editor'=>'Lecture et édition','none'=>'Aucun accès'] as $key=>$label):?><option value="<?=$key?>" <?=$role===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label class="checkbox-field"><input type="checkbox" name="enabled" value="1" <?=!$identityEdit||$identityEdit['enabled']?'checked':''?>> Utilisateur actif — consomme une place</label><label>Entreprise<select name="company_id"><option value="">À affecter — utilisateur inactif</option><?php foreach($identityCompanies as $c):?><option value="<?=h($c['id'])?>" <?=(string)($identityEdit['company_id']??'')===(string)$c['id']?'selected':''?>><?=h($c['display_name'])?> · SLM <?=h($c['slm_license_id']??'—')?></option><?php endforeach;?></select></label></div>
<?php if($internal):?><p>Connexion avec le compte interne <strong><?=h($identityEdit['login_name'])?></strong>. <a href="<?=h(url('/?page=accounts'))?>">Définir ou réinitialiser son mot de passe Ogipen</a>.</p><?php else:?><label for="identity-public-key">Clé publique ECDSA P-256 <?=$identityEdit?'— laisser vide pour conserver la clé actuelle':''?></label><textarea id="identity-public-key" name="public_key" rows="6" maxlength="4096" placeholder="-----BEGIN PUBLIC KEY-----" <?=$identityEdit?'':'required'?> spellcheck="false" autocomplete="off"></textarea><p class="hint">Utilisez la fiche d’accès de ce compte Windows. Aucune clé privée n’est demandée. Attribuer un rôle ne remplace pas l’authentification Windows ni les contrôles de licence.</p><?php endif;?>
<div class="form-actions"><button><?=$identityEdit?'Enregistrer les modifications':'Ajouter l’utilisateur'?></button><?php if($identityEdit):?><a href="<?=h(url('/?page=identities'))?>">Annuler</a><?php endif;?></div></form></section>
